def zigzag_convert(s, num_rows):
    n = len(s)
    if num_rows <= 1 or num_rows >= n:
        return s
    cycle = 2 * num_rows - 2
    result = []
    for row in range(num_rows):
        i = row
        while i < n:
            result.append(s[i])
            if row != 0 and row != num_rows - 1:
                j = i + cycle - 2 * row
                if j < n:
                    result.append(s[j])
            i += cycle
    return ''.join(result)

